     1→//! Run with
     2→//!
     3→//! ```sh
     4→//! cargo run -p example-beacon-api-sidecar-fetcher -- node --full
     5→//! ```
     6→//!
     7→//! This launches a regular reth instance and subscribes to payload attributes event stream.
     8→//!
     9→//! **NOTE**: This expects that the CL client is running an http server on `localhost:5052` and is
    10→//! configured to emit payload attributes events.
    11→//!
    12→//! See beacon Node API: <https://ethereum.github.io/beacon-APIs/>
    13→
    14→#![warn(unused_crate_dependencies)]
    15→
    16→use std::{
    17→    collections::VecDeque,
    18→    net::{IpAddr, Ipv4Addr},
    19→};
    20→
    21→use alloy_primitives::B256;
    22→use clap::Parser;
    23→use futures_util::{stream::FuturesUnordered, StreamExt};
    24→use mined_sidecar::MinedSidecarStream;
    25→use reth_ethereum::{
    26→    cli::{chainspec::EthereumChainSpecParser, interface::Cli},
    27→    node::{builder::NodeHandle, EthereumNode},
    28→    provider::CanonStateSubscriptions,
    29→};
    30→
    31→pub mod mined_sidecar;
    32→
    33→fn main() {
    34→    Cli::<EthereumChainSpecParser, BeaconSidecarConfig>::parse()
    35→        .run(|builder, beacon_config| async move {
    36→            // launch the node
    37→            let NodeHandle { node, node_exit_future } =
    38→                builder.node(EthereumNode::default()).launch().await?;
    39→
    40→            let notifications: reth_ethereum::provider::CanonStateNotificationStream =
    41→                node.provider.canonical_state_stream();
    42→
    43→            let pool = node.pool.clone();
    44→
    45→            node.task_executor.spawn(async move {
    46→                let mut sidecar_stream = MinedSidecarStream {
    47→                    events: notifications,
    48→                    pool,
    49→                    beacon_config,
    50→                    client: reqwest::Client::new(),
    51→                    pending_requests: FuturesUnordered::new(),
    52→                    queued_actions: VecDeque::new(),
    53→                };
    54→
    55→                while let Some(result) = sidecar_stream.next().await {
    56→                    match result {
    57→                        Ok(blob_transaction) => {
    58→                            // Handle successful transaction
    59→                            println!("Processed BlobTransaction: {blob_transaction:?}");
    60→                        }
    61→                        Err(e) => {
    62→                            // Handle errors specifically
    63→                            eprintln!("Failed to process transaction: {e:?}");
    64→                        }
    65→                    }
    66→                }
    67→            });
    68→
    69→            node_exit_future.await
    70→        })
    71→        .unwrap();
    72→}
