    81→/// A Stream that processes CanonStateNotifications and retrieves BlobTransactions from the beacon
    82→/// client.
    83→///
    84→/// First checks if the blob sidecar for a given EIP4844 is stored locally, if not attempts to
    85→/// retrieve it from the CL Layer
    86→#[must_use = "streams do nothing unless polled"]
    87→pub struct MinedSidecarStream<St, P> {
    88→    pub events: St,
    89→    pub pool: P,
    90→    pub beacon_config: BeaconSidecarConfig,
    91→    pub client: reqwest::Client,
    92→    pub pending_requests: FuturesUnordered<SidecarsFuture>,
    93→    pub queued_actions: VecDeque<BlobTransactionEvent>,
    94→}
    95→
    96→impl<St, P> MinedSidecarStream<St, P>
    97→where
    98→    St: Stream<Item = CanonStateNotification> + Send + Unpin + 'static,
    99→    P: TransactionPoolExt + Unpin + 'static,
   100→{
   101→    fn process_block(&mut self, block: &RecoveredBlock<reth_ethereum::Block>) {
   102→        let txs: Vec<_> = block
   103→            .body()
   104→            .transactions()
   105→            .filter(|tx| tx.is_eip4844())
   106→            .map(|tx| (tx.clone(), tx.blob_count().unwrap_or(0) as usize))
   107→            .collect();
   108→
   109→        let mut all_blobs_available = true;
   110→        let mut actions_to_queue: Vec<BlobTransactionEvent> = Vec::new();
   111→
   112→        if txs.is_empty() {
   113→            return
   114→        }
   115→
   116→        match self.pool.get_all_blobs_exact(txs.iter().map(|(tx, _)| *tx.tx_hash()).collect()) {
   117→            Ok(blobs) => {
   118→                actions_to_queue.reserve_exact(txs.len());
   119→                for ((tx, _), sidecar) in txs.iter().zip(blobs.into_iter()) {
   120→                    if let PooledTransactionVariant::Eip4844(transaction) = tx
   121→                        .clone()
   122→                        .try_into_pooled_eip4844(Arc::unwrap_or_clone(sidecar))
   123→                        .expect("should not fail to convert blob tx if it is already eip4844")
   124→                    {
   125→                        let block_metadata = BlockMetadata {
   126→                            block_hash: block.hash(),
   127→                            block_number: block.number,
   128→                            gas_used: block.gas_used,
   129→                        };
   130→                        actions_to_queue.push(BlobTransactionEvent::Mined(MinedBlob {
   131→                            transaction,
   132→                            block_metadata,
   133→                        }));
   134→                    }
   135→                }
   136→            }
   137→            Err(_err) => {
   138→                all_blobs_available = false;
   139→            }
   140→        };
   141→
   142→        // if any blob is missing we must instead query the consensus layer.
   143→        if all_blobs_available {
   144→            self.queued_actions.extend(actions_to_queue);
   145→        } else {
   146→            let client_clone = self.client.clone();
   147→            let block_root = block.hash();
   148→            let block_clone = block.clone();
   149→            let sidecar_url = self.beacon_config.sidecar_url(block_root);
   150→            let query =
   151→                Box::pin(fetch_blobs_for_block(client_clone, sidecar_url, block_clone, txs));
   152→            self.pending_requests.push(query);
   153→        }
   154→    }
   155→}
   156→
   157→impl<St, P> Stream for MinedSidecarStream<St, P>
   158→where
   159→    St: Stream<Item = CanonStateNotification> + Send + Unpin + 'static,
   160→    P: TransactionPoolExt + Unpin + 'static,
   161→{
   162→    type Item = Result<BlobTransactionEvent, SideCarError>;
   163→
   164→    /// Attempt to pull the next BlobTransaction from the stream.
   165→    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
   166→        let this = self.get_mut();
   167→
   168→        // Request locally first, otherwise request from CL
   169→        loop {
   170→            if let Some(mined_sidecar) = this.queued_actions.pop_front() {
   171→                return Poll::Ready(Some(Ok(mined_sidecar)))
   172→            }
   173→
   174→            // Check if any pending requests are ready and append to buffer
   175→            while let Poll::Ready(Some(pending_result)) = this.pending_requests.poll_next_unpin(cx)
   176→            {
   177→                match pending_result {
   178→                    Ok(mined_sidecars) => {
   179→                        for sidecar in mined_sidecars {
   180→                            this.queued_actions.push_back(sidecar);
   181→                        }
   182→                    }
   183→                    Err(err) => return Poll::Ready(Some(Err(err))),
   184→                }
   185→            }
   186→
   187→            while let Poll::Ready(Some(notification)) = this.events.poll_next_unpin(cx) {
   188→                {
   189→                    match notification {
   190→                        CanonStateNotification::Commit { new } => {
   191→                            for (_, block) in new.blocks().iter() {
   192→                                this.process_block(block);
   193→                            }
   194→                        }
   195→                        CanonStateNotification::Reorg { old, new } => {
   196→                            // handle reorged blocks
   197→                            for (_, block) in old.blocks().iter() {
   198→                                let txs: Vec<BlobTransactionEvent> = block
   199→                                    .body()
   200→                                    .transactions()
   201→                                    .filter(|tx| tx.is_eip4844())
   202→                                    .map(|tx| {
   203→                                        let transaction_hash = *tx.tx_hash();
   204→                                        let block_metadata = BlockMetadata {
   205→                                            block_hash: new.tip().hash(),
   206→                                            block_number: new.tip().number(),
   207→                                            gas_used: new.tip().gas_used(),
   208→                                        };
   209→                                        BlobTransactionEvent::Reorged(ReorgedBlob {
   210→                                            transaction_hash,
   211→                                            block_metadata,
   212→                                        })
   213→                                    })
   214→                                    .collect();
   215→                                this.queued_actions.extend(txs);
   216→                            }
   217→
   218→                            for (_, block) in new.blocks().iter() {
   219→                                this.process_block(block);
   220→                            }
   221→                        }
   222→                    }
   223→                }
   224→            }
   225→        }
   226→    }
   227→}
