   229→/// Query the Beacon Layer for missing BlobTransactions
   230→async fn fetch_blobs_for_block(
   231→    client: reqwest::Client,
   232→    url: String,
   233→    block: RecoveredBlock<reth_ethereum::Block>,
   234→    txs: Vec<(reth_ethereum::TransactionSigned, usize)>,
   235→) -> Result<Vec<BlobTransactionEvent>, SideCarError> {
   236→    let response = match client.get(url).header("Accept", "application/json").send().await {
   237→        Ok(response) => response,
   238→        Err(err) => return Err(SideCarError::ReqwestError(err)),
   239→    };
   240→
   241→    if !response.status().is_success() {
   242→        return match response.status() {
   243→            StatusCode::BAD_REQUEST => {
   244→                Err(SideCarError::InvalidBlockID("Invalid request to server.".to_string()))
   245→            }
   246→            StatusCode::NOT_FOUND => {
   247→                Err(SideCarError::BlockNotFound("Requested block not found.".to_string()))
   248→            }
   249→            StatusCode::INTERNAL_SERVER_ERROR => {
   250→                Err(SideCarError::InternalError("Server encountered an error.".to_string()))
   251→            }
   252→            _ => Err(SideCarError::UnknownError(
   253→                response.status().as_u16(),
   254→                "Unhandled HTTP status.".to_string(),
   255→            )),
   256→        }
   257→    }
   258→
   259→    let bytes = match response.bytes().await {
   260→        Ok(b) => b,
   261→        Err(e) => return Err(SideCarError::NetworkError(e.to_string())),
   262→    };
   263→
   264→    let blobs_bundle: BeaconBlobBundle = match serde_json::from_slice(&bytes) {
   265→        Ok(b) => b,
   266→        Err(e) => return Err(SideCarError::DeserializationError(e.to_string())),
   267→    };
   268→
   269→    let mut sidecar_iterator = SidecarIterator::new(blobs_bundle);
   270→
   271→    let sidecars: Vec<BlobTransactionEvent> = txs
   272→        .iter()
   273→        .filter_map(|(tx, blob_len)| {
   274→            sidecar_iterator.next_sidecar(*blob_len).and_then(|sidecar| {
   275→                if let PooledTransactionVariant::Eip4844(transaction) = tx
   276→                    .clone()
   277→                    .try_into_pooled_eip4844(BlobTransactionSidecarVariant::Eip4844(sidecar))
   278→                    .expect("should not fail to convert blob tx if it is already eip4844")
   279→                {
   280→                    let block_metadata = BlockMetadata {
   281→                        block_hash: block.hash(),
   282→                        block_number: block.number,
   283→                        gas_used: block.gas_used,
   284→                    };
   285→                    Some(BlobTransactionEvent::Mined(MinedBlob { transaction, block_metadata }))
   286→                } else {
   287→                    None
   288→                }
   289→            })
   290→        })
   291→        .collect();
   292→
   293→    Ok(sidecars)
   294→}
