   452→    /// Creates a [`ForkFilter`] for the block described by [Head].
   453→    pub fn fork_filter(&self, head: Head) -> ForkFilter {
   454→        let forks = self.hardforks.forks_iter().filter_map(|(_, condition)| {
   455→            // We filter out TTD-based forks w/o a pre-known block since those do not show up in
   456→            // the fork filter.
   457→            Some(match condition {
   458→                ForkCondition::Block(block) |
   459→                ForkCondition::TTD { fork_block: Some(block), .. } => ForkFilterKey::Block(block),
   460→                ForkCondition::Timestamp(time) => ForkFilterKey::Time(time),
   461→                _ => return None,
   462→            })
   463→        });
   464→
   465→        ForkFilter::new(head, self.genesis_hash(), self.genesis_timestamp(), forks)
   466→    }
   467→
   468→    /// Compute the [`ForkId`] for the given [`Head`] following eip-6122 spec.
   469→    ///
   470→    /// Note: In case there are multiple hardforks activated at the same block or timestamp, only
   471→    /// the first gets applied.
   472→    pub fn fork_id(&self, head: &Head) -> ForkId {
   473→        let mut forkhash = ForkHash::from(self.genesis_hash());
   474→
   475→        // this tracks the last applied block or timestamp fork. This is necessary for optimism,
   476→        // because for the optimism hardforks both the optimism and the corresponding ethereum
   477→        // hardfork can be configured in `ChainHardforks` if it enables ethereum equivalent
   478→        // functionality (e.g. additional header,body fields) This is set to 0 so that all
   479→        // block based hardforks are skipped in the following loop
   480→        let mut current_applied = 0;
   481→
   482→        // handle all block forks before handling timestamp based forks. see: https://eips.ethereum.org/EIPS/eip-6122
   483→        for (_, cond) in self.hardforks.forks_iter() {
   484→            // handle block based forks and the sepolia merge netsplit block edge case (TTD
   485→            // ForkCondition with Some(block))
   486→            if let ForkCondition::Block(block) |
   487→            ForkCondition::TTD { fork_block: Some(block), .. } = cond
   488→            {
   489→                if head.number >= block {
   490→                    // skip duplicated hardforks: hardforks enabled at genesis block
   491→                    if block != current_applied {
   492→                        forkhash += block;
   493→                        current_applied = block;
   494→                    }
   495→                } else {
   496→                    // we can return here because this block fork is not active, so we set the
   497→                    // `next` value
   498→                    return ForkId { hash: forkhash, next: block }
   499→                }

